// --- Single Tag Component ---

interface TagProps {
  item: AnimatedPriceTagsProps["tags"][number];
  index: number;
  total: number;
  canvasScale: number;
  canvasHeight: number;
  isSingleLayout?: boolean;
  iconXOffset: number;
  iconYOffset: number;
  textXOffset: number;
  textYOffset: number;
}

const Tag: React.FC<TagProps> = ({
  item,
  index,
  total,
  canvasScale,
  canvasHeight,
  isSingleLayout = false,
  iconXOffset,
  iconYOffset,
  textXOffset,
  textYOffset,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Dimensions based on canvas scale and layout preference
  const scaleMultiplier = isSingleLayout ? 1.6 : 1.0;
  const w = 240 * canvasScale * scaleMultiplier;
  const h = 480 * canvasScale * scaleMultiplier;
  const topW = w * 0.45;
  const cornerY = h * 0.2;
  const holeRadius = w * 0.08;
  const holeY = cornerY * 0.5;

  // Geometry computation for the tag path
  const topY = -holeY;
  const bottomY = h - holeY;
  const cornerYOffset = cornerY - holeY;

  const tagOuterPath = `M ${-topW / 2} ${topY} L ${topW / 2} ${topY} L ${w / 2} ${cornerYOffset} L ${w / 2} ${bottomY} L ${-w / 2} ${bottomY} L ${-w / 2} ${cornerYOffset} Z`;
  const tagHolePath = `M 0 ${-holeRadius} A ${holeRadius} ${holeRadius} 0 1 0 0 ${holeRadius} A ${holeRadius} ${holeRadius} 0 1 0 0 ${-holeRadius}`;
  const combinedTagPath = `${tagOuterPath} ${tagHolePath}`;

  const stringPath = `M 0 ${-holeRadius} C ${-w * 0.15} ${-canvasHeight * 0.3} ${-w * 0.05} ${-canvasHeight * 0.6} 0 ${-canvasHeight} C ${w * 0.05} ${-canvasHeight * 0.6} ${w * 0.15} ${-canvasHeight * 0.3} 0 ${-holeRadius}`;

  // Animation logic (no delay if it's the only chosen tag)
  const staggerDelay = isSingleLayout ? 0 : 8;
  const entranceFrame = index * staggerDelay;
  const localFrame = frame - entranceFrame;

  // Drop animation (Y axis)
  const dropSpring = spring({
    frame: Math.max(0, localFrame),
    fps,
    config: { damping: 12, mass: 1.2, stiffness: 80 },
  });
  const yPos = localFrame < 0 ? -canvasHeight * 1.5 : interpolate(dropSpring, [0, 1], [-canvasHeight * 1.5, 0]);

  // Swing animation (Rotation)
  const angleSpring = spring({
    frame: Math.max(0, localFrame),
    fps,
    config: { damping: 4, stiffness: 25, mass: 1 },
  });
  const startAngle = index % 2 === 0 ? 25 : -25;
  const rotation = localFrame < 0 ? startAngle : interpolate(angleSpring, [0, 1], [startAngle, 0]);

  // Darker shade for accents
  const darkAccent = "rgba(0,0,0,0.15)";
  const iconSize = w * 0.4;

  return (
    <div
      style={{
        position: "relative",
        width: w,
        height: h,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        transformOrigin: `50% ${holeY}px`,
        transform: `translateY(${yPos}px) rotate(${rotation}deg)`,
        transition: "none",
        opacity: localFrame > -5 ? 1 : 0, // Keep mounted but hidden before entrance
      }}
    >
      {/* String */}
      <svg
        style={{ position: "absolute", top: holeY, left: "50%", transform: "translateX(-50%)", width: w, height: canvasHeight, overflow: "visible" }}
      >
        <path d={stringPath} fill="none" stroke="#2a2a2a" strokeWidth={w * 0.02} strokeLinecap="round" />
      </svg>

      {/* Tag Base Shape with Hole Cutout */}
      <svg
        style={{ position: "absolute", top: holeY, left: "50%", transform: "translateX(-50%)", width: w, height: h, overflow: "visible" }}
      >
        {/* Shadow/Depth layer */}
        <path d={combinedTagPath} fill="rgba(0,0,0,0.1)" transform="translate(4, 6)" fillRule="evenodd" />
        {/* Main body */}
        <path d={combinedTagPath} fill={item.color} fillRule="evenodd" />
        
        {/* Top crease/angle shading */}
        <path d={`M ${-topW / 2} ${topY} L ${topW / 2} ${topY} L ${w / 2} ${cornerYOffset} L ${-w / 2} ${cornerYOffset} Z`} fill={darkAccent} />
        
        {/* Hole Ring */}
        <circle cx="0" cy="0" r={holeRadius + w * 0.02} fill="none" stroke={darkAccent} strokeWidth={w * 0.02} />
      </svg>

      {/* Content Container (perfectly bounded inside the tag width to ensure no text or icons overflow) */}
      <div
        style={{
          position: "absolute",
          top: cornerY,
          left: "50%",
          transform: "translateX(-50%)",
          width: w,
          height: h - cornerY,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingLeft: w * 0.12,
          paddingRight: w * 0.12,
          boxSizing: "border-box",
        }}
      >
        {/* Icon Container centered and safely padded */}
        <div style={{ height: "40%", display: "flex", alignItems: "center", justifyContent: "center", transform: `translate(${iconXOffset * canvasScale}px, ${iconYOffset * canvasScale}px)` }}>
          {getIconComponent(item.icon, iconSize, "#ffffff")}
        </div>

        {/* Space adjustment in place of the removed separator line */}
        <div style={{ marginTop: h * 0.02, marginBottom: h * 0.02 }} />

        {/* Text Label constrained within tag bounds with auto line breaking */}
        <div
          style={{
            fontFamily: oswaldFamily,
            fontWeight: 600,
            fontSize: w * 0.14,
            lineHeight: 1.1,
            color: "#ffffff",
            textTransform: "uppercase",
            letterSpacing: w * 0.01,
            textAlign: "center",
            width: "100%",
            textShadow: "1px 1px 3px rgba(0,0,0,0.2)",
            whiteSpace: "normal",
            wordBreak: "break-all",
            overflowWrap: "break-word",
            transform: `translate(${textXOffset * canvasScale}px, ${textYOffset * canvasScale}px)`,
          }}
        >
          {item.label}
        </div>
      </div>
    </div>
  );
};

// --- Main Component ---

const AnimatedPriceTags: React.FC<AnimatedPriceTagsProps> = ({
  backgroundColor = "#f0f0f0",
  transparentBackground = true,
  durationInSeconds = 8,
  selectedIndex = 0,
  showAll = true,
  iconXOffset = 0,
  iconYOffset = 0,
  textXOffset = 0,
  textYOffset = 0,
  tags = [
    { label: "BUDGET", color: "#319C68", icon: "backpack" },
    { label: "CHEAP", color: "#FBB636", icon: "camera" },
    { label: "LUXURY", color: "#8568B2", icon: "suitcase" },
    { label: "FREE", color: "#3CB1B0", icon: "ticket" },
    { label: "EXPENSIVE", color: "#DF4540", icon: "plane" },
  ],
}) => {
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Render logic based on whether we show all or just a single chosen tag
  const visibleTags = useMemo(() => {
    if (showAll) {
      return tags.map((tag, idx) => ({ tag, originalIndex: idx }));
    }
    // Clamp the selected index to valid bounds
    const safeIndex = Math.max(0, Math.min(selectedIndex, tags.length - 1));
    return [{ tag: tags[safeIndex], originalIndex: 0 }];
  }, [tags, showAll, selectedIndex]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          width: "100%",
          height: "100%",
          alignItems: "flex-start",
          justifyContent: "center",
          paddingTop: showAll ? height * 0.25 : height * 0.2, // Offset vertically depending on tag size
          gap: width * 0.04, // Space between tags
        }}
      >
        {visibleTags.map((item, index) => (
          <Tag 
            key={`${item.tag.label}-${index}`} 
            item={item.tag} 
            index={item.originalIndex} 
            total={visibleTags.length} 
            canvasScale={s} 
            canvasHeight={height} 
            isSingleLayout={!showAll}
            iconXOffset={iconXOffset}
            iconYOffset={iconYOffset}
            textXOffset={textXOffset}
            textYOffset={textYOffset}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export default AnimatedPriceTags;